module barrel_shifter(
    input [7:0] in, input [2:0] ctrl,
    output [7:0] out
);
// Define wires for each stage of the barrel shifter
wire [7:0] mux_stage1, mux_stage2;
// First stage of the barrel shifter
assign mux_stage1 = (ctrl[2]) ? {in[3:0], in[7:4]} : in;
// Second stage of the barrel shifter
assign mux_stage2 = (ctrl[1]) ? {mux_stage1[5:0], mux_stage1[7:6]} : mux_stage1;
// Third stage of the barrel shifter
assign out = (ctrl[0]) ? {mux_stage2[6:0], mux_stage2[7]} : mux_stage2;
endmodule
